export default class PlaneWithHtml extends Mesh {
    // ...
        await new Promise((resolve, reject) => {
            html2canvas(this.div, {
                backgroundColor,
                removeContainer: true
            }).then(async (canvas) => {
                this.setGeoSize(canvas.width, canvas.height);
                this.material.map = new CanvasTexture(canvas);
                this.material.map.anisotropy = threeLoader.anisotropy;
                this.material.needsUpdate = true;
                await new Promise(resolve => requestAnimationFrame(resolve));
                this.visible = true;
                this.div.remove();
                resolve();
            });
        });
    // ...
}
// ---- file: package/SpriteWithHtml.js ----
export default class SpriteWithHtml extends Sprite {
    // ...
        await new Promise((resolve, reject) => {
            html2canvas(this.div, {
                backgroundColor,
                removeContainer: true
            }).then(async (canvas) => {
                this.scale.set(canvas.width, canvas.height, 1);
                this.material.map = new CanvasTexture(canvas);
                this.material.map.anisotropy = threeLoader.anisotropy;
                this.material.alphaTest = 0.1;
                this.material.needsUpdate = true;
                await new Promise(resolve => requestAnimationFrame(resolve));
                this.visible = true;
                this.div.remove();
                resolve();
            });
        });
    // ...
}
